def park(name="Command"):
    return Command.no_requirements(co.park).named(name)


def flickering(signal: Ref):
    def f():
        val = signal.get()
        if val:
            signal.set(False)
        return val

    return f


def collected(ref) -> bool:
    for _ in range(5):
        if ref() is None:
            return True
        gc.collect()
    return ref() is None


