def test_if_true_one_shot_schedules_on_every_true_poll(scheduler):
    signal, counter = Ref(False), Ref(0)
    trigger = Trigger(scheduler, signal.get)
    trigger.if_true(Command.no_requirements(lambda: counter.increment_and_get()).named("One Shot"))
