def test_command_scoping(scheduler):
    inner_ran, inner_signal = Ref(False), Ref(False)

    def inner_body():
        while True:
            inner_ran.set(True)
            yield from co.park()

    inner = Command.no_requirements(inner_body).named("Inner")

    def outer_body():
        Trigger(scheduler, inner_signal.get).on_true(inner)
        yield from co.park()

    scheduler.schedule(Command.no_requirements(outer_body).named("Outer"))
    scheduler.run()
    assert not inner_ran.get()
    inner_signal.set(True)
    scheduler.run()
    assert inner_ran.get()
    inner_ran.set(False)
    scheduler.run()
    assert not inner_ran.get()


class LambdaScope(BindingScope):
    def __init__(self, fn):
        self.fn = fn

    def active(self):
        return self.fn()


