CONCRETE = [RobotMode.AUTONOMOUS, RobotMode.TELEOPERATED, RobotMode.UTILITY]


def test_trigger_created_in_one_mode_survives_transitions_to_all_other_modes(scheduler, robot):
    for source in CONCRETE:
        for destination in CONCRETE:
            if source == destination:
                continue
            robot.robot_mode = source
            signal = Ref(False)
            trigger = Trigger(scheduler, signal.get)
            source_cmd = park("SourceModeCommand")
            trigger.while_true(source_cmd)
            signal.set(True)
            scheduler.run()
            assert scheduler.is_running(source_cmd), f"{source} -> {destination}"
            robot.robot_mode = destination
            scheduler.run()
            assert not scheduler.is_running(source_cmd), f"{source} -> {destination}"
            signal.set(False)
            scheduler.run()
            dest_cmd = park("DestinationModeCommand")
            trigger.while_true(dest_cmd)
            signal.set(True)
            scheduler.run()
            assert scheduler.is_running(dest_cmd), f"{source} -> {destination}"
            signal.set(False)
            scheduler.run()
            assert not scheduler.is_running(dest_cmd), f"{source} -> {destination}"


def test_trigger_from_exiting_command_does_not_fire(scheduler):
    condition, ran = Ref(False), Ref(False)

    def inner_body():
        ran.set(True)
        yield from co.park()

    inner = Command.no_requirements(inner_body).named("Inner")

    def awaited_body():
        yield
        condition.set(True)

    awaited = Command.no_requirements(awaited_body).named("Awaited")

    def outer_body():
        Trigger(scheduler, condition.get).on_true(inner)
        yield from co.await_(awaited)

    outer = Command.no_requirements(outer_body).named("Outer")
    scheduler.schedule(outer)
    scheduler.run()
    assert [c.name() for c in scheduler.get_running_commands()] == ["Outer", "Awaited"]
    scheduler.run()
    assert scheduler.get_running_commands() == []
    assert condition.get()
    assert not ran.get()
    scheduler.run()
    assert scheduler.get_running_commands() == []
    assert not ran.get()


