def test_trigger_does_not_unbind_when_command_scope_inactive(scheduler):
    signal, ran, trigger_ref = Ref(False), Ref(False), Ref()
    inner = Command.no_requirements(lambda: ran.set(True)).named("Inner")

    def outer_body():
        t = Trigger(scheduler, signal.get)
        trigger_ref.set(t)
        t.on_true(inner)
        yield from co.park()

    outer = Command.no_requirements(outer_body).named("Outer")
    scheduler.schedule(outer)
    scheduler.run()
    assert scheduler.is_running(outer)
    signal.set(True)
    scheduler.run()
    assert ran.get()
    scheduler.cancel(outer)
    scheduler.run()
    assert not scheduler.is_running(outer)
    assert trigger_ref.get()()
    signal.set(False)
    assert trigger_ref.get()()
    scheduler.run()
    assert not trigger_ref.get()()


