def test_unscoped_trigger_can_be_garbage_collected(scheduler, events, robot):
    robot.opmode_id, robot.opmode_name = 1, "opmode"
    signal = Ref(False)
    command = park()
    ref = weakref.ref(Trigger(scheduler, signal.get).on_true(command))
    scheduler.run()
    assert not collected(ref), "Trigger should not be garbage collected while still in scope"
    robot.opmode_id, robot.opmode_name = 0, ""
    signal.set(True)
    scheduler.run()
    assert events == [], "The trigger should not have fired"
    assert collected(ref), "Trigger should be garbage collected after going out of scope"


def test_multi_press(scheduler, clock):
    clock.set(1.0)
    signal = Ref(False)
    mp = Trigger(scheduler, signal.get).multi_press(3, 1.0)
    scheduler.run()
    assert not mp()
    for t, expect in ((1.1, False), (1.2, False), (1.3, True)):
        clock.set(t)
        signal.set(True)
        scheduler.run()
        assert mp() is expect
        signal.set(False)
        scheduler.run()
    clock.set(2.0)
    signal.set(True)
    scheduler.run()
    assert mp(), "Should still fire as there are 4 presses within last 1s"
    signal.set(False)
    scheduler.run()
    clock.set(2.2)
    scheduler.run()
    assert mp(), "Should still fire as there are 3 presses within last 1s"
    clock.set(2.4)
    scheduler.run()
    assert not mp(), "Should not fire after presses expire"


